    const p4Schema: Schema = {
      type: Type.OBJECT,
      properties: {
        improvements: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              originalBullet: { type: Type.STRING },
