'use client';

import { useRef, useState, DragEvent, ChangeEvent } from 'react';
import { Upload, FileText, X, ClipboardPaste, AlertCircle } from 'lucide-react';

interface ResumeUploaderProps {
  onFileSelect: (file: File | null) => void;
  selectedFile: File | null;
  pastedText: string;
  onPastedTextChange: (text: string) => void;
  mode: 'file' | 'text';
  onModeChange: (mode: 'file' | 'text') => void;
}

const MAX_FILE_SIZE_BYTES = 5 * 1024 * 1024; // 5MB

export default function ResumeUploader({
  onFileSelect,
  selectedFile,
  pastedText,
  onPastedTextChange,
  mode,
  onModeChange,
}: ResumeUploaderProps) {
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);

  const validateAndSelectFile = (file: File) => {
    setFileError(null);
    const isPdf =
      file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
    if (!isPdf) {
      setFileError('Invalid file format. Please upload a text-based PDF (.pdf) file.');
      return;
    }
    if (file.size > MAX_FILE_SIZE_BYTES) {
      setFileError('File exceeds 5MB limit. Please upload a smaller PDF or paste resume text.');
      return;
    }
    onFileSelect(file);
  };

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      validateAndSelectFile(file);
    }
    e.target.value = '';
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) {
      validateAndSelectFile(file);
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
  };

  const wordCount = pastedText.trim().split(/\s+/).filter(Boolean).length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
      {/* Mode Toggle Tabs */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '0.4rem',
          background: 'rgba(0,0,0,0.25)',
          padding: '0.25rem',
          borderRadius: '10px',
          border: '1px solid rgba(255,255,255,0.08)',
        }}
      >
        <button
          type="button"
          onClick={() => {
            setFileError(null);
            onModeChange('file');
          }}
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '0.4rem',
            padding: '0.45rem 0.75rem',
            borderRadius: '8px',
            border: 'none',
            background: mode === 'file' ? 'rgba(99, 102, 241, 0.25)' : 'transparent',
            color: mode === 'file' ? '#ffffff' : '#9ca3af',
            fontSize: '0.8rem',
            fontWeight: 600,
            cursor: 'pointer',
            transition: 'all 0.2s',
          }}
        >
          <Upload size={14} /> Upload PDF
        </button>

        <button
          type="button"
          onClick={() => {
            setFileError(null);
            onModeChange('text');
          }}
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '0.4rem',
            padding: '0.45rem 0.75rem',
            borderRadius: '8px',
            border: 'none',
            background: mode === 'text' ? 'rgba(99, 102, 241, 0.25)' : 'transparent',
            color: mode === 'text' ? '#ffffff' : '#9ca3af',
            fontSize: '0.8rem',
            fontWeight: 600,
