            transition: 'all 0.2s',
          }}
        >
          <ClipboardPaste size={14} /> Paste Resume Text
        </button>
      </div>

      {fileError && (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.5rem',
            padding: '0.6rem 0.85rem',
            borderRadius: '8px',
            background: 'rgba(239, 68, 68, 0.12)',
            border: '1px solid rgba(239, 68, 68, 0.3)',
            color: '#fca5a5',
            fontSize: '0.8rem',
          }}
        >
