                  width: '48px',
                  height: '48px',
                  borderRadius: '12px',
                  background: 'rgba(99, 102, 241, 0.15)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#818cf8',
                }}
              >
                <Upload size={22} />
              </div>
              <div>
                <div style={{ fontWeight: 600, color: '#e5e7eb', fontSize: '0.95rem' }}>
                  Drag & drop your resume PDF here
                </div>
                <div style={{ color: '#9ca3af', fontSize: '0.8rem', marginTop: '0.25rem' }}>
                  or click to browse files (Text-based PDF, max 5MB)
                </div>
              </div>
            </div>
          ) : (
            <div
              style={{
                height: '240px',
                border: '1px solid rgba(99, 102, 241, 0.4)',
                borderRadius: '12px',
                background: 'rgba(99, 102, 241, 0.08)',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                padding: '1.5rem',
                textAlign: 'center',
                gap: '0.75rem',
              }}
            >
              <div
                style={{
                  width: '48px',
                  height: '48px',
                  borderRadius: '12px',
                  background: 'rgba(16, 185, 129, 0.15)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#34d399',
                }}
              >
                <FileText size={22} />
              </div>
              <div>
                <div style={{ fontWeight: 600, color: '#ffffff', fontSize: '0.95rem', wordBreak: 'break-word' }}>
                  {selectedFile.name}
                </div>
                <div style={{ color: '#9ca3af', fontSize: '0.8rem', marginTop: '0.2rem' }}>
                  {formatFileSize(selectedFile.size)} • Ready for extraction
                </div>
              </div>
              <button
                type="button"
                onClick={() => onFileSelect(null)}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '0.35rem',
                  background: 'rgba(239, 68, 68, 0.15)',
                  border: '1px solid rgba(239, 68, 68, 0.3)',
